public class DataSerializer {

    private static final ObjectMapper converter = new ObjectMapper();

    public static String serializeData(Object data, boolean formattedOutput) {
        if (data == null) return null;
        try {
            if (formattedOutput) {
                converter.enable(SerializationFeature.INDENT_OUTPUT);
            } else {
                converter.disable(SerializationFeature.INDENT_OUTPUT);
            }
            return converter.writeValueAsString(data);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}

public class SolidTriangleUpward implements IShapeMarker {

    @Override
    public void render(Graphics2D graphics, float centerX, float centerY, float dimension, Color fillColor) {
        // 获取三角形顶点
        float[][] vertices = ShapeUtilities.triangleUpwardVertices(centerX, centerY, dimension);
        Polygon polygon = new Polygon();
        for (float[] vertex : vertices) {
            polygon.addPoint(Math.round(vertex[0]), Math.round(vertex[1]));
        }
        graphics.setColor(fillColor);
        graphics.fillPolygon(polygon);
    }
}

