public final class TextBuilderUtilities {

    private TextBuilderUtilities() {

    }

    public static <T> StringBuilder concatenateItems(StringBuilder textBuilder, String delimiter, Collection<T> items) {
        if (textBuilder == null || items == null) return textBuilder;
        StringJoiner joiner = new StringJoiner(delimiter);
        for (T item : items) {
            joiner.add(item.toString());
        }
        textBuilder.append(joiner.toString());
        return textBuilder;
    }
}

